with orders as (select restaurant_key, count(*) as delivered_orders, round(sum(order_total),2) as revenue, round(avg(delivery_minutes),1) as avg_delivery_minutes from {{ ref('fact_orders') }} where status='delivered' group by 1), ratings as (select restaurant_key, round(avg(rating),2) as avg_rating from {{ ref('fact_reviews') }} group by 1) select r.restaurant_key,r.restaurant_name,r.city,r.cuisine,coalesce(o.delivered_orders,0) as delivered_orders,coalesce(o.revenue,0) as revenue,o.avg_delivery_minutes,v.avg_rating from {{ ref('dim_restaurant') }} r left join orders o on r.restaurant_key=o.restaurant_key left join ratings v on r.restaurant_key=v.restaurant_key